const states=new WeakMap();
export function initBehaviorTaskIndex(runner,parent){const owners=parent?states.get(parent)?.owners:new Map();if(!owners||parent&&owners.get(parent.runId)!==parent)throw Error('상위 태스크 소유자가 없어요.');states.set(runner,{owners,parent:parent||null,local:new Map()});owners.set(runner.runId,runner);}
export function registerBehaviorTask(runner,node,memory){const state=states.get(runner);if(!state||state.owners.get(runner.runId)!==runner)throw Error('종료된 태스크 소유자예요.');state.local.set(memory.handle,{runner,node:node.id,m:memory});}
export function lookupBehaviorTask(runner,handle){if(typeof handle!=='string')return null;const state=states.get(runner),colon=handle.indexOf(':');if(!state||colon<=0)return null;const owner=state.owners.get(handle.slice(0,colon)),entry=owner&&states.get(owner)?.local.get(handle);if(!entry||entry.m.handle!==handle||owner.memory.get(entry.node)!==entry.m)return null;for(let at=owner;at;at=states.get(at)?.parent)if(at===runner)return entry;return null;}
export function retireBehaviorTask(runner,memory){if(!memory)return;delete memory.taskData;const local=states.get(runner)?.local;if(local?.get(memory.handle)?.m===memory)local.delete(memory.handle);}
export function wakeBehaviorTaskOwners(runner){for(let at=runner;at;at=states.get(at)?.parent)at.wake=true;}
export function closeBehaviorTaskIndex(runner){const state=states.get(runner);if(!state)return;for(const entry of state.local.values())delete entry.m.taskData;state.local.clear();state.owners.delete(runner.runId);if(!state.parent)state.owners.clear();state.parent=null;}
export function inspectBehaviorTaskIndex(runner){const state=states.get(runner);return{owners:state?.owners.size||0,tasks:state?.local.size||0};}
export const behaviorTaskIndexContract=Object.freeze({ownership:'Private weak runner state; one owner registry per root tree, one entry per executing/finishing/aborting activation. Exact runID:serial handle lookup, then current memory identity and descendant ancestry checks. Child calls cannot access siblings/parents, actors keep separate registries.',cost:'Memory/Get/Set/Clear, FinishTask, IsExecuting/IsAborting and FinishAbort lookup no longer enumerate node memories or descend all subtrees. Map lookups plus ancestor-depth check; no per-frame index rebuild or global task-count cap.',lifetime:'Register before task start callback. Finish notification retains access, then retirement deletes index and JSON payload; abort/deferred cleanup retains it until retirement. Root/child shutdown releases owner entries and parent references even after callback errors.',unchanged:'Node/name/path GetTaskHandle discovery, ordinary tree scheduling, status/debug snapshots, observer/service work and asset loading are separate costs. No native BTTask class model, FPS/device guarantee or new SDK.'});
